function getFilteredGraph(){let visible=new Set(currentModelData.nodes.map(n=>n.id));if(activeViewMode==='business')visible=new Set(currentModelData.nodes.filter(n=>['Business Capability','Business Application','Application Service','Business Service','Service Offering'].includes(n.type)).map(n=>n.id));else if(activeViewMode==='infraOnly')visible=new Set(currentModelData.nodes.filter(n=>isInfraType(n.type)).map(n=>n.id));else if(activeViewMode==='serviceInfra')visible=new Set(currentModelData.nodes.filter(n=>['Business Application','Application Service','Business Service','Service Offering'].includes(n.type)||isInfraType(n.type)).map(n=>n.id));else if(activeViewMode==='neighborhood'&&neighborhoodNodeId)visible=getNeighborhoodNodeSet(neighborhoodNodeId,focusHopCount);else if(layerTypeMap[activeViewMode])visible=new Set(currentModelData.nodes.filter(n=>layerTypeMap[activeViewMode].includes(n.type)).map(n=>n.id));let edges=currentModelData.edges.map((e,i)=>({...e,_index:i})).filter(e=>visible.has(e.from)&&visible.has(e.to));if(activeRelationshipFilter!=='all'){edges=edges.filter(edgeMatchesRelationshipFilter);const edgeNodes=new Set();edges.forEach(e=>{edgeNodes.add(e.from);edgeNodes.add(e.to)});if(neighborhoodNodeId&&visible.has(neighborhoodNodeId))edgeNodes.add(neighborhoodNodeId);visible=new Set([...visible].filter(id=>edgeNodes.has(id)))}return applyDomainClustering(currentModelData.nodes.filter(n=>visible.has(n.id)),edges)}
